INSERT INTO `chuong` (`ten_chuong`, `so_thu_tu`) VALUES ('Các tội xâm phạm tính mạng, sức khỏe', 1) ON DUPLICATE KEY UPDATE `ten_chuong`=VALUES(`ten_chuong`), `so_thu_tu`=VALUES(`so_thu_tu`);
INSERT INTO `chuong` (`ten_chuong`, `so_thu_tu`) VALUES ('Các tội xâm phạm sở hữu', 2) ON DUPLICATE KEY UPDATE `ten_chuong`=VALUES(`ten_chuong`), `so_thu_tu`=VALUES(`so_thu_tu`);
INSERT INTO `chuong` (`ten_chuong`, `so_thu_tu`) VALUES ('Các tội xâm phạm an toàn công cộng, trật tự công cộng', 3) ON DUPLICATE KEY UPDATE `ten_chuong`=VALUES(`ten_chuong`), `so_thu_tu`=VALUES(`so_thu_tu`);
INSERT INTO `chuong` (`ten_chuong`, `so_thu_tu`) VALUES ('Các tội phạm về chức vụ', 4) ON DUPLICATE KEY UPDATE `ten_chuong`=VALUES(`ten_chuong`), `so_thu_tu`=VALUES(`so_thu_tu`);
INSERT INTO `chuong` (`ten_chuong`, `so_thu_tu`) VALUES ('Các tội phạm về ma túy', 5) ON DUPLICATE KEY UPDATE `ten_chuong`=VALUES(`ten_chuong`), `so_thu_tu`=VALUES(`so_thu_tu`);
INSERT INTO `chuong` (`ten_chuong`, `so_thu_tu`) VALUES ('Các tội xâm phạm trật tự quản lý kinh tế', 6) ON DUPLICATE KEY UPDATE `ten_chuong`=VALUES(`ten_chuong`), `so_thu_tu`=VALUES(`so_thu_tu`);
INSERT INTO `chuong` (`ten_chuong`, `so_thu_tu`) VALUES ('Các tội xâm phạm danh dự, nhân phẩm', 7) ON DUPLICATE KEY UPDATE `ten_chuong`=VALUES(`ten_chuong`), `so_thu_tu`=VALUES(`so_thu_tu`);
INSERT INTO `chuong` (`ten_chuong`, `so_thu_tu`) VALUES ('Các tội xâm phạm quyền sở hữu', 8) ON DUPLICATE KEY UPDATE `ten_chuong`=VALUES(`ten_chuong`), `so_thu_tu`=VALUES(`so_thu_tu`);
INSERT INTO `chuong` (`ten_chuong`, `so_thu_tu`) VALUES ('Các tội xâm phạm trật tự công cộng', 9) ON DUPLICATE KEY UPDATE `ten_chuong`=VALUES(`ten_chuong`), `so_thu_tu`=VALUES(`so_thu_tu`);
INSERT INTO `dieu_luat` (`id`,`chuong_id`,`tieu_de`,`tom_tat`,`tu_khoa`,`khung_hinh_phat`,`can_cu_boi_thuong`,`ghi_chu_quyen_loi`) VALUES (123, (SELECT `id` FROM `chuong` WHERE `ten_chuong`='Các tội xâm phạm tính mạng, sức khỏe'), 'Tội giết người', 'Hành vi cố ý tước đoạt tính mạng người khác một cách trái pháp luật.', 'giết người tước đoạt tính mạng sát hại cố ý', '7–20 năm tù, tù chung thân hoặc tử hình (có tình tiết định khung tăng nặng)', 'Điều 591 Bộ luật Dân sự 2015 — bồi thường thiệt hại do tính mạng bị xâm phạm', NULL) ON DUPLICATE KEY UPDATE `chuong_id`=VALUES(`chuong_id`), `tieu_de`=VALUES(`tieu_de`), `tom_tat`=VALUES(`tom_tat`), `tu_khoa`=VALUES(`tu_khoa`), `khung_hinh_phat`=VALUES(`khung_hinh_phat`), `can_cu_boi_thuong`=VALUES(`can_cu_boi_thuong`), `ghi_chu_quyen_loi`=VALUES(`ghi_chu_quyen_loi`);
INSERT INTO `khoan` (`dieu_luat_id`,`so_khoan`,`dieu_kien`,`noi_dung`,`quyen_loi`,`tu_khoa`,`ti_le_ton_thuong_min`,`ti_le_ton_thuong_max`,`gia_tri_tai_san_min`,`gia_tri_tai_san_max`,`so_nguoi_chet_min`) VALUES (123, 1, 'Có tình tiết định khung tăng nặng (giết từ 2 người trở lên, giết người dưới 16 tuổi, có tính chất côn đồ, vì động cơ đê hèn...)', 'Người nào giết người thuộc một trong các trường hợp định khung tăng nặng thì bị phạt tù 12–20 năm, tù chung thân hoặc tử hình.', 'Thân nhân người bị hại (cha mẹ, vợ/chồng, con...) có quyền yêu cầu người phạm tội bồi thường: chi phí hợp lý cho việc cứu chữa, bồi dưỡng, chăm sóc trước khi nạn nhân chết; chi phí mai táng; tiền cấp dưỡng cho những người mà nạn nhân có nghĩa vụ cấp dưỡng; khoản bù đắp tổn thất tinh thần cho thân nhân (tối đa 100 lần mức lương cơ sở nếu không thỏa thuận được). Có thể yêu cầu ngay trong quá trình giải quyết vụ án hình sự (không cần khởi kiện dân sự riêng).', 'giết nhiều người giết trẻ em côn đồ đê hèn man rợ', NULL, NULL, NULL, NULL, NULL) ON DUPLICATE KEY UPDATE `dieu_kien`=VALUES(`dieu_kien`), `noi_dung`=VALUES(`noi_dung`), `quyen_loi`=VALUES(`quyen_loi`), `tu_khoa`=VALUES(`tu_khoa`), `ti_le_ton_thuong_min`=VALUES(`ti_le_ton_thuong_min`), `ti_le_ton_thuong_max`=VALUES(`ti_le_ton_thuong_max`), `gia_tri_tai_san_min`=VALUES(`gia_tri_tai_san_min`), `gia_tri_tai_san_max`=VALUES(`gia_tri_tai_san_max`), `so_nguoi_chet_min`=VALUES(`so_nguoi_chet_min`);
INSERT INTO `khoan` (`dieu_luat_id`,`so_khoan`,`dieu_kien`,`noi_dung`,`quyen_loi`,`tu_khoa`,`ti_le_ton_thuong_min`,`ti_le_ton_thuong_max`,`gia_tri_tai_san_min`,`gia_tri_tai_san_max`,`so_nguoi_chet_min`) VALUES (123, 2, 'Không thuộc các trường hợp định khung tăng nặng ở khoản 1', 'Phạm tội không thuộc các trường hợp trên thì bị phạt tù từ 7 đến 15 năm.', 'Tương tự khoản 1: thân nhân người bị hại được quyền yêu cầu bồi thường chi phí cứu chữa trước khi chết, chi phí mai táng, tiền cấp dưỡng và tổn thất tinh thần theo Điều 591 Bộ luật Dân sự.', 'giết người trường hợp thông thường không tăng nặng', NULL, NULL, NULL, NULL, NULL) ON DUPLICATE KEY UPDATE `dieu_kien`=VALUES(`dieu_kien`), `noi_dung`=VALUES(`noi_dung`), `quyen_loi`=VALUES(`quyen_loi`), `tu_khoa`=VALUES(`tu_khoa`), `ti_le_ton_thuong_min`=VALUES(`ti_le_ton_thuong_min`), `ti_le_ton_thuong_max`=VALUES(`ti_le_ton_thuong_max`), `gia_tri_tai_san_min`=VALUES(`gia_tri_tai_san_min`), `gia_tri_tai_san_max`=VALUES(`gia_tri_tai_san_max`), `so_nguoi_chet_min`=VALUES(`so_nguoi_chet_min`);
INSERT INTO `khoan` (`dieu_luat_id`,`so_khoan`,`dieu_kien`,`noi_dung`,`quyen_loi`,`tu_khoa`,`ti_le_ton_thuong_min`,`ti_le_ton_thuong_max`,`gia_tri_tai_san_min`,`gia_tri_tai_san_max`,`so_nguoi_chet_min`) VALUES (123, 3, 'Mới ở giai đoạn chuẩn bị phạm tội, chưa thực hiện hành vi', 'Người chuẩn bị phạm tội có thể bị phạt tù từ 1 đến 5 năm.', 'Ở giai đoạn này chưa có hậu quả chết người xảy ra nên thường chưa phát sinh quyền yêu cầu bồi thường theo Điều 591; nếu hành vi chuẩn bị đã gây thiệt hại thực tế khác (vd. tài sản, sức khỏe) thì người bị thiệt hại vẫn có quyền yêu cầu bồi thường tương ứng với thiệt hại đó.', 'chuẩn bị phạm tội chưa thực hiện', NULL, NULL, NULL, NULL, NULL) ON DUPLICATE KEY UPDATE `dieu_kien`=VALUES(`dieu_kien`), `noi_dung`=VALUES(`noi_dung`), `quyen_loi`=VALUES(`quyen_loi`), `tu_khoa`=VALUES(`tu_khoa`), `ti_le_ton_thuong_min`=VALUES(`ti_le_ton_thuong_min`), `ti_le_ton_thuong_max`=VALUES(`ti_le_ton_thuong_max`), `gia_tri_tai_san_min`=VALUES(`gia_tri_tai_san_min`), `gia_tri_tai_san_max`=VALUES(`gia_tri_tai_san_max`), `so_nguoi_chet_min`=VALUES(`so_nguoi_chet_min`);
INSERT INTO `dieu_luat` (`id`,`chuong_id`,`tieu_de`,`tom_tat`,`tu_khoa`,`khung_hinh_phat`,`can_cu_boi_thuong`,`ghi_chu_quyen_loi`) VALUES (168, (SELECT `id` FROM `chuong` WHERE `ten_chuong`='Các tội xâm phạm sở hữu'), 'Tội cướp tài sản', 'Dùng vũ lực, đe dọa dùng vũ lực ngay tức khắc hoặc thủ đoạn khác làm người bị tấn công lâm vào tình trạng không thể chống cự nhằm chiếm đoạt tài sản.', 'cướp tài sản dùng vũ lực đe dọa chiếm đoạt cướp giật giật dọc trấn lột túi xách dây chuyền xe máy', '3–20 năm tù hoặc tù chung thân, tùy tình tiết và giá trị tài sản', 'Điều 589 Bộ luật Dân sự 2015 (tài sản) — kết hợp Điều 590/591 nếu có thương tích hoặc chết người', NULL) ON DUPLICATE KEY UPDATE `chuong_id`=VALUES(`chuong_id`), `tieu_de`=VALUES(`tieu_de`), `tom_tat`=VALUES(`tom_tat`), `tu_khoa`=VALUES(`tu_khoa`), `khung_hinh_phat`=VALUES(`khung_hinh_phat`), `can_cu_boi_thuong`=VALUES(`can_cu_boi_thuong`), `ghi_chu_quyen_loi`=VALUES(`ghi_chu_quyen_loi`);
INSERT INTO `khoan` (`dieu_luat_id`,`so_khoan`,`dieu_kien`,`noi_dung`,`quyen_loi`,`tu_khoa`,`ti_le_ton_thuong_min`,`ti_le_ton_thuong_max`,`gia_tri_tai_san_min`,`gia_tri_tai_san_max`,`so_nguoi_chet_min`) VALUES (168, 1, 'Trường hợp cơ bản, chưa có tình tiết tăng nặng', 'Người nào dùng vũ lực, đe dọa dùng vũ lực ngay tức khắc hoặc có hành vi khác làm cho người bị tấn công lâm vào tình trạng không thể chống cự được nhằm chiếm đoạt tài sản thì bị phạt tù từ 3 đến 10 năm.', 'Bạn có quyền yêu cầu người phạm tội trả lại tài sản đã lấy hoặc bồi thường giá trị tương đương nếu tài sản không còn, cộng với lợi ích đáng lẽ thu được từ việc sử dụng tài sản (Điều 589 Bộ luật Dân sự). Yêu cầu này có thể nêu ngay trong vụ án hình sự.', 'cướp cơ bản dùng vũ lực đe dọa', NULL, NULL, NULL, NULL, NULL) ON DUPLICATE KEY UPDATE `dieu_kien`=VALUES(`dieu_kien`), `noi_dung`=VALUES(`noi_dung`), `quyen_loi`=VALUES(`quyen_loi`), `tu_khoa`=VALUES(`tu_khoa`), `ti_le_ton_thuong_min`=VALUES(`ti_le_ton_thuong_min`), `ti_le_ton_thuong_max`=VALUES(`ti_le_ton_thuong_max`), `gia_tri_tai_san_min`=VALUES(`gia_tri_tai_san_min`), `gia_tri_tai_san_max`=VALUES(`gia_tri_tai_san_max`), `so_nguoi_chet_min`=VALUES(`so_nguoi_chet_min`);
INSERT INTO `khoan` (`dieu_luat_id`,`so_khoan`,`dieu_kien`,`noi_dung`,`quyen_loi`,`tu_khoa`,`ti_le_ton_thuong_min`,`ti_le_ton_thuong_max`,`gia_tri_tai_san_min`,`gia_tri_tai_san_max`,`so_nguoi_chet_min`) VALUES (168, 2, 'Có tổ chức, tính chất chuyên nghiệp, dùng vũ khí, gây thương tích...', 'Phạm tội có tổ chức, có tính chất chuyên nghiệp, dùng vũ khí, gây thương tích... thì bị phạt tù từ 7 đến 15 năm.', 'Ngoài quyền đòi lại/bồi thường tài sản (Điều 589), nếu bị gây thương tích bạn còn được quyền yêu cầu thêm: chi phí cứu chữa, bồi dưỡng phục hồi sức khỏe, thu nhập bị mất trong thời gian điều trị và khoản bù đắp tổn thất tinh thần (Điều 590 Bộ luật Dân sự).', 'có tổ chức chuyên nghiệp vũ khí gây thương tích nhẹ', NULL, 30, NULL, NULL, NULL) ON DUPLICATE KEY UPDATE `dieu_kien`=VALUES(`dieu_kien`), `noi_dung`=VALUES(`noi_dung`), `quyen_loi`=VALUES(`quyen_loi`), `tu_khoa`=VALUES(`tu_khoa`), `ti_le_ton_thuong_min`=VALUES(`ti_le_ton_thuong_min`), `ti_le_ton_thuong_max`=VALUES(`ti_le_ton_thuong_max`), `gia_tri_tai_san_min`=VALUES(`gia_tri_tai_san_min`), `gia_tri_tai_san_max`=VALUES(`gia_tri_tai_san_max`), `so_nguoi_chet_min`=VALUES(`so_nguoi_chet_min`);
INSERT INTO `khoan` (`dieu_luat_id`,`so_khoan`,`dieu_kien`,`noi_dung`,`quyen_loi`,`tu_khoa`,`ti_le_ton_thuong_min`,`ti_le_ton_thuong_max`,`gia_tri_tai_san_min`,`gia_tri_tai_san_max`,`so_nguoi_chet_min`) VALUES (168, 3, 'Tài sản chiếm đoạt trị giá 200–500 triệu đồng, hoặc gây thương tích 31–60%', 'Phạm tội chiếm đoạt tài sản trị giá từ 200 triệu đến dưới 500 triệu đồng, hoặc gây thương tích tỉ lệ tổn thương cơ thể từ 31–60% thì bị phạt tù từ 12 đến 20 năm.', 'Mức thiệt hại ở đây thường lớn hơn: bạn có quyền yêu cầu bồi thường toàn bộ giá trị tài sản bị chiếm đoạt (Điều 589), cộng chi phí điều trị, thu nhập bị mất, chi phí người chăm sóc (nếu tỉ lệ tổn thương cao cần người chăm sóc) và tổn thất tinh thần — tối đa 50 lần mức lương cơ sở cho phần tổn thất tinh thần nếu không thỏa thuận được (Điều 590).', 'tài sản hai trăm đến năm trăm triệu thương tích ba mươi mốt đến sáu mươi phần trăm', 31, 60, 200, 500, NULL) ON DUPLICATE KEY UPDATE `dieu_kien`=VALUES(`dieu_kien`), `noi_dung`=VALUES(`noi_dung`), `quyen_loi`=VALUES(`quyen_loi`), `tu_khoa`=VALUES(`tu_khoa`), `ti_le_ton_thuong_min`=VALUES(`ti_le_ton_thuong_min`), `ti_le_ton_thuong_max`=VALUES(`ti_le_ton_thuong_max`), `gia_tri_tai_san_min`=VALUES(`gia_tri_tai_san_min`), `gia_tri_tai_san_max`=VALUES(`gia_tri_tai_san_max`), `so_nguoi_chet_min`=VALUES(`so_nguoi_chet_min`);
INSERT INTO `khoan` (`dieu_luat_id`,`so_khoan`,`dieu_kien`,`noi_dung`,`quyen_loi`,`tu_khoa`,`ti_le_ton_thuong_min`,`ti_le_ton_thuong_max`,`gia_tri_tai_san_min`,`gia_tri_tai_san_max`,`so_nguoi_chet_min`) VALUES (168, 4, 'Tài sản chiếm đoạt từ 500 triệu đồng trở lên, hoặc làm chết người', 'Phạm tội trong trường hợp đặc biệt nghiêm trọng (chiếm đoạt tài sản 500 triệu đồng trở lên, làm chết người) thì bị phạt tù 18–20 năm hoặc tù chung thân.', 'Nếu nạn nhân tử vong: thân nhân được quyền yêu cầu bồi thường theo Điều 591 (chi phí cứu chữa trước khi chết, chi phí mai táng, tiền cấp dưỡng, tổn thất tinh thần tối đa 100 lần mức lương cơ sở), cộng với quyền đòi lại/bồi thường giá trị tài sản bị chiếm đoạt theo Điều 589.', 'đặc biệt nghiêm trọng năm trăm triệu trở lên làm chết người', NULL, NULL, 500, NULL, 1) ON DUPLICATE KEY UPDATE `dieu_kien`=VALUES(`dieu_kien`), `noi_dung`=VALUES(`noi_dung`), `quyen_loi`=VALUES(`quyen_loi`), `tu_khoa`=VALUES(`tu_khoa`), `ti_le_ton_thuong_min`=VALUES(`ti_le_ton_thuong_min`), `ti_le_ton_thuong_max`=VALUES(`ti_le_ton_thuong_max`), `gia_tri_tai_san_min`=VALUES(`gia_tri_tai_san_min`), `gia_tri_tai_san_max`=VALUES(`gia_tri_tai_san_max`), `so_nguoi_chet_min`=VALUES(`so_nguoi_chet_min`);
INSERT INTO `dieu_luat` (`id`,`chuong_id`,`tieu_de`,`tom_tat`,`tu_khoa`,`khung_hinh_phat`,`can_cu_boi_thuong`,`ghi_chu_quyen_loi`) VALUES (174, (SELECT `id` FROM `chuong` WHERE `ten_chuong`='Các tội xâm phạm sở hữu'), 'Tội lừa đảo chiếm đoạt tài sản', 'Dùng thủ đoạn gian dối để chiếm đoạt tài sản của người khác.', 'lừa đảo gian dối chiếm đoạt tài sản online chuyển khoản', 'Cảnh cáo, cải tạo không giam giữ đến 3 năm, hoặc phạt tù 6 tháng – 20 năm tùy giá trị tài sản', 'Điều 589 Bộ luật Dân sự 2015 — bồi thường thiệt hại do tài sản bị xâm phạm', NULL) ON DUPLICATE KEY UPDATE `chuong_id`=VALUES(`chuong_id`), `tieu_de`=VALUES(`tieu_de`), `tom_tat`=VALUES(`tom_tat`), `tu_khoa`=VALUES(`tu_khoa`), `khung_hinh_phat`=VALUES(`khung_hinh_phat`), `can_cu_boi_thuong`=VALUES(`can_cu_boi_thuong`), `ghi_chu_quyen_loi`=VALUES(`ghi_chu_quyen_loi`);
INSERT INTO `khoan` (`dieu_luat_id`,`so_khoan`,`dieu_kien`,`noi_dung`,`quyen_loi`,`tu_khoa`,`ti_le_ton_thuong_min`,`ti_le_ton_thuong_max`,`gia_tri_tai_san_min`,`gia_tri_tai_san_max`,`so_nguoi_chet_min`) VALUES (174, 1, 'Tài sản chiếm đoạt trị giá từ 2 đến dưới 50 triệu đồng (hoặc dưới 2 triệu nhưng đã từng bị xử lý)', 'Người nào bằng thủ đoạn gian dối chiếm đoạt tài sản của người khác trị giá từ 2 triệu đến dưới 50 triệu đồng (hoặc dưới 2 triệu nhưng đã bị xử phạt hành chính / có tiền án chưa xóa) thì bị phạt cải tạo không giam giữ đến 3 năm hoặc phạt tù từ 6 tháng đến 3 năm.', 'Bạn có quyền yêu cầu người phạm tội hoàn trả đúng số tiền/tài sản đã bị lừa, hoặc bồi thường giá trị tương đương nếu không còn khả năng hoàn trả nguyên trạng, cộng với thiệt hại phát sinh hợp lý khác do việc mất tài sản gây ra (Điều 589 Bộ luật Dân sự). Có thể yêu cầu ngay trong vụ án hình sự mà không cần khởi kiện dân sự riêng.', 'hai triệu đến năm mươi triệu lừa đảo nhỏ', NULL, NULL, 2, 50, NULL) ON DUPLICATE KEY UPDATE `dieu_kien`=VALUES(`dieu_kien`), `noi_dung`=VALUES(`noi_dung`), `quyen_loi`=VALUES(`quyen_loi`), `tu_khoa`=VALUES(`tu_khoa`), `ti_le_ton_thuong_min`=VALUES(`ti_le_ton_thuong_min`), `ti_le_ton_thuong_max`=VALUES(`ti_le_ton_thuong_max`), `gia_tri_tai_san_min`=VALUES(`gia_tri_tai_san_min`), `gia_tri_tai_san_max`=VALUES(`gia_tri_tai_san_max`), `so_nguoi_chet_min`=VALUES(`so_nguoi_chet_min`);
INSERT INTO `khoan` (`dieu_luat_id`,`so_khoan`,`dieu_kien`,`noi_dung`,`quyen_loi`,`tu_khoa`,`ti_le_ton_thuong_min`,`ti_le_ton_thuong_max`,`gia_tri_tai_san_min`,`gia_tri_tai_san_max`,`so_nguoi_chet_min`) VALUES (174, 2, 'Có tổ chức, tính chất chuyên nghiệp, hoặc tài sản 50–200 triệu đồng', 'Phạm tội có tổ chức, tính chất chuyên nghiệp, chiếm đoạt tài sản 50–200 triệu đồng... thì bị phạt tù từ 2 đến 7 năm.', 'Cũng theo Điều 589: quyền được hoàn trả toàn bộ số tiền/tài sản bị chiếm đoạt hoặc bồi thường giá trị tương đương, kể cả khi bị lừa qua nhiều lần/nhiều đối tượng trong đường dây.', 'năm mươi đến hai trăm triệu có tổ chức chuyên nghiệp', NULL, NULL, 50, 200, NULL) ON DUPLICATE KEY UPDATE `dieu_kien`=VALUES(`dieu_kien`), `noi_dung`=VALUES(`noi_dung`), `quyen_loi`=VALUES(`quyen_loi`), `tu_khoa`=VALUES(`tu_khoa`), `ti_le_ton_thuong_min`=VALUES(`ti_le_ton_thuong_min`), `ti_le_ton_thuong_max`=VALUES(`ti_le_ton_thuong_max`), `gia_tri_tai_san_min`=VALUES(`gia_tri_tai_san_min`), `gia_tri_tai_san_max`=VALUES(`gia_tri_tai_san_max`), `so_nguoi_chet_min`=VALUES(`so_nguoi_chet_min`);
INSERT INTO `khoan` (`dieu_luat_id`,`so_khoan`,`dieu_kien`,`noi_dung`,`quyen_loi`,`tu_khoa`,`ti_le_ton_thuong_min`,`ti_le_ton_thuong_max`,`gia_tri_tai_san_min`,`gia_tri_tai_san_max`,`so_nguoi_chet_min`) VALUES (174, 3, 'Tài sản chiếm đoạt trị giá 200 đến dưới 500 triệu đồng', 'Chiếm đoạt tài sản trị giá 200 triệu đến dưới 500 triệu đồng thì bị phạt tù từ 7 đến 15 năm.', 'Quyền yêu cầu bồi thường toàn bộ giá trị tài sản đã mất (Điều 589). Với số tiền lớn, nên yêu cầu tòa án tuyên buộc hoàn trả/bồi thường ngay trong bản án hình sự để thuận tiện thi hành án sau này.', 'hai trăm đến năm trăm triệu', NULL, NULL, 200, 500, NULL) ON DUPLICATE KEY UPDATE `dieu_kien`=VALUES(`dieu_kien`), `noi_dung`=VALUES(`noi_dung`), `quyen_loi`=VALUES(`quyen_loi`), `tu_khoa`=VALUES(`tu_khoa`), `ti_le_ton_thuong_min`=VALUES(`ti_le_ton_thuong_min`), `ti_le_ton_thuong_max`=VALUES(`ti_le_ton_thuong_max`), `gia_tri_tai_san_min`=VALUES(`gia_tri_tai_san_min`), `gia_tri_tai_san_max`=VALUES(`gia_tri_tai_san_max`), `so_nguoi_chet_min`=VALUES(`so_nguoi_chet_min`);
INSERT INTO `khoan` (`dieu_luat_id`,`so_khoan`,`dieu_kien`,`noi_dung`,`quyen_loi`,`tu_khoa`,`ti_le_ton_thuong_min`,`ti_le_ton_thuong_max`,`gia_tri_tai_san_min`,`gia_tri_tai_san_max`,`so_nguoi_chet_min`) VALUES (174, 4, 'Tài sản chiếm đoạt trị giá từ 500 triệu đồng trở lên', 'Chiếm đoạt tài sản trị giá 500 triệu đồng trở lên thì bị phạt tù từ 12 đến 20 năm hoặc tù chung thân.', 'Tương tự các khoản trên: quyền được bồi thường toàn bộ giá trị tài sản bị chiếm đoạt (Điều 589). Với vụ việc giá trị đặc biệt lớn, thường có nhiều bị hại — nên phối hợp cùng các bị hại khác để được xem xét bồi thường theo tỉ lệ tài sản thu hồi được.', 'năm trăm triệu trở lên đặc biệt lớn', NULL, NULL, 500, NULL, NULL) ON DUPLICATE KEY UPDATE `dieu_kien`=VALUES(`dieu_kien`), `noi_dung`=VALUES(`noi_dung`), `quyen_loi`=VALUES(`quyen_loi`), `tu_khoa`=VALUES(`tu_khoa`), `ti_le_ton_thuong_min`=VALUES(`ti_le_ton_thuong_min`), `ti_le_ton_thuong_max`=VALUES(`ti_le_ton_thuong_max`), `gia_tri_tai_san_min`=VALUES(`gia_tri_tai_san_min`), `gia_tri_tai_san_max`=VALUES(`gia_tri_tai_san_max`), `so_nguoi_chet_min`=VALUES(`so_nguoi_chet_min`);
INSERT INTO `dieu_luat` (`id`,`chuong_id`,`tieu_de`,`tom_tat`,`tu_khoa`,`khung_hinh_phat`,`can_cu_boi_thuong`,`ghi_chu_quyen_loi`) VALUES (260, (SELECT `id` FROM `chuong` WHERE `ten_chuong`='Các tội xâm phạm an toàn công cộng, trật tự công cộng'), 'Tội vi phạm quy định về tham gia giao thông đường bộ', 'Người tham gia giao thông đường bộ vi phạm quy định về an toàn giao thông gây thiệt hại cho tính mạng, sức khỏe, tài sản người khác.', 'tai nạn giao thông lái xe gây chết người vi phạm luật giao thông', 'Phạt tiền, cải tạo không giam giữ đến 3 năm, hoặc phạt tù 1 – 15 năm tùy hậu quả', 'Điều 601 Bộ luật Dân sự 2015 (nguồn nguy hiểm cao độ) — kết hợp Điều 590/591 tùy hậu quả về sức khỏe hoặc tính mạng', NULL) ON DUPLICATE KEY UPDATE `chuong_id`=VALUES(`chuong_id`), `tieu_de`=VALUES(`tieu_de`), `tom_tat`=VALUES(`tom_tat`), `tu_khoa`=VALUES(`tu_khoa`), `khung_hinh_phat`=VALUES(`khung_hinh_phat`), `can_cu_boi_thuong`=VALUES(`can_cu_boi_thuong`), `ghi_chu_quyen_loi`=VALUES(`ghi_chu_quyen_loi`);
INSERT INTO `khoan` (`dieu_luat_id`,`so_khoan`,`dieu_kien`,`noi_dung`,`quyen_loi`,`tu_khoa`,`ti_le_ton_thuong_min`,`ti_le_ton_thuong_max`,`gia_tri_tai_san_min`,`gia_tri_tai_san_max`,`so_nguoi_chet_min`) VALUES (260, 1, 'Làm chết 1 người, hoặc thương tích từ 61% trở lên, hoặc thiệt hại tài sản 100–500 triệu đồng', 'Vi phạm quy định về an toàn giao thông đường bộ làm chết 1 người, hoặc gây thương tích tỉ lệ tổn thương cơ thể 61% trở lên, hoặc gây thiệt hại tài sản từ 100 triệu đến dưới 500 triệu đồng thì bị phạt tiền 30–100 triệu đồng, cải tạo không giam giữ đến 3 năm hoặc phạt tù từ 1 đến 5 năm.', 'Nếu bị thương: chi phí cứu chữa, thu nhập bị mất, chi phí người chăm sóc, tổn thất tinh thần (Điều 590). Nếu người thân tử vong: chi phí cứu chữa trước khi chết, chi phí mai táng, tiền cấp dưỡng, tổn thất tinh thần tối đa 100 lần mức lương cơ sở (Điều 591). Thiệt hại xe cộ/tài sản được bồi thường riêng theo Điều 589. Chủ xe (nếu khác người điều khiển) có thể cùng liên đới chịu trách nhiệm theo Điều 601.', 'chết một người thương tích sáu mươi mốt phần trăm tài sản trăm đến năm trăm triệu', 61, NULL, 100, 500, 1) ON DUPLICATE KEY UPDATE `dieu_kien`=VALUES(`dieu_kien`), `noi_dung`=VALUES(`noi_dung`), `quyen_loi`=VALUES(`quyen_loi`), `tu_khoa`=VALUES(`tu_khoa`), `ti_le_ton_thuong_min`=VALUES(`ti_le_ton_thuong_min`), `ti_le_ton_thuong_max`=VALUES(`ti_le_ton_thuong_max`), `gia_tri_tai_san_min`=VALUES(`gia_tri_tai_san_min`), `gia_tri_tai_san_max`=VALUES(`gia_tri_tai_san_max`), `so_nguoi_chet_min`=VALUES(`so_nguoi_chet_min`);
INSERT INTO `khoan` (`dieu_luat_id`,`so_khoan`,`dieu_kien`,`noi_dung`,`quyen_loi`,`tu_khoa`,`ti_le_ton_thuong_min`,`ti_le_ton_thuong_max`,`gia_tri_tai_san_min`,`gia_tri_tai_san_max`,`so_nguoi_chet_min`) VALUES (260, 2, 'Không có giấy phép lái xe, có nồng độ cồn/ma túy, bỏ chạy trốn tránh trách nhiệm, hoặc làm chết 2 người', 'Không có giấy phép lái xe, trong tình trạng có sử dụng rượu bia/ma túy, bỏ chạy để trốn tránh trách nhiệm, làm chết 2 người... thì bị phạt tù từ 3 đến 10 năm.', 'Tương tự khoản 1 nhưng với nhiều người bị hại hơn, mỗi gia đình nạn nhân có quyền yêu cầu bồi thường độc lập theo Điều 591 (nếu chết) hoặc Điều 590 (nếu bị thương), cộng Điều 589 cho thiệt hại tài sản. Tình tiết lái xe bỏ chạy có thể là căn cứ đề nghị mức bồi thường tổn thất tinh thần ở mức tối đa khung luật định.', 'không giấy phép lái xe say rượu ma túy bỏ chạy chết hai người', NULL, NULL, NULL, NULL, 2) ON DUPLICATE KEY UPDATE `dieu_kien`=VALUES(`dieu_kien`), `noi_dung`=VALUES(`noi_dung`), `quyen_loi`=VALUES(`quyen_loi`), `tu_khoa`=VALUES(`tu_khoa`), `ti_le_ton_thuong_min`=VALUES(`ti_le_ton_thuong_min`), `ti_le_ton_thuong_max`=VALUES(`ti_le_ton_thuong_max`), `gia_tri_tai_san_min`=VALUES(`gia_tri_tai_san_min`), `gia_tri_tai_san_max`=VALUES(`gia_tri_tai_san_max`), `so_nguoi_chet_min`=VALUES(`so_nguoi_chet_min`);
INSERT INTO `khoan` (`dieu_luat_id`,`so_khoan`,`dieu_kien`,`noi_dung`,`quyen_loi`,`tu_khoa`,`ti_le_ton_thuong_min`,`ti_le_ton_thuong_max`,`gia_tri_tai_san_min`,`gia_tri_tai_san_max`,`so_nguoi_chet_min`) VALUES (260, 3, 'Làm chết 3 người trở lên, hoặc thiệt hại tài sản từ 1,5 tỷ đồng trở lên', 'Làm chết 3 người trở lên hoặc gây thiệt hại tài sản 1,5 tỷ đồng trở lên thì bị phạt tù từ 7 đến 15 năm.', 'Mỗi thân nhân của từng nạn nhân tử vong có quyền yêu cầu bồi thường riêng theo Điều 591; bị hại về tài sản (xe cộ, hàng hóa, công trình...) yêu cầu bồi thường theo Điều 589. Với vụ việc nhiều bị hại, nên tập hợp hồ sơ chung để tòa án giải quyết đồng thời phần dân sự trong vụ án hình sự.', 'chết ba người trở lên tài sản một tỷ rưỡi', NULL, NULL, 1500, NULL, 3) ON DUPLICATE KEY UPDATE `dieu_kien`=VALUES(`dieu_kien`), `noi_dung`=VALUES(`noi_dung`), `quyen_loi`=VALUES(`quyen_loi`), `tu_khoa`=VALUES(`tu_khoa`), `ti_le_ton_thuong_min`=VALUES(`ti_le_ton_thuong_min`), `ti_le_ton_thuong_max`=VALUES(`ti_le_ton_thuong_max`), `gia_tri_tai_san_min`=VALUES(`gia_tri_tai_san_min`), `gia_tri_tai_san_max`=VALUES(`gia_tri_tai_san_max`), `so_nguoi_chet_min`=VALUES(`so_nguoi_chet_min`);
INSERT INTO `dieu_luat` (`id`,`chuong_id`,`tieu_de`,`tom_tat`,`tu_khoa`,`khung_hinh_phat`,`can_cu_boi_thuong`,`ghi_chu_quyen_loi`) VALUES (353, (SELECT `id` FROM `chuong` WHERE `ten_chuong`='Các tội phạm về chức vụ'), 'Tội tham ô tài sản', 'Người có chức vụ, quyền hạn lợi dụng chức vụ chiếm đoạt tài sản mà mình có trách nhiệm quản lý.', 'tham ô tài sản chức vụ quyền hạn chiếm đoạt công quỹ biển thủ tham nhũng thủ quỹ kế toán ngân sách cơ quan nhà nước', '2 – 20 năm tù, tù chung thân hoặc tử hình tùy giá trị tài sản', NULL, 'Đây là tội xâm phạm tài sản của Nhà nước/cơ quan/tổ chức (không có người bị hại là cá nhân), nên cá nhân thường không có quyền yêu cầu bồi thường trực tiếp. Cơ quan/tổ chức bị thiệt hại có quyền yêu cầu người phạm tội hoàn trả/bồi thường tài sản theo Điều 589 Bộ luật Dân sự.') ON DUPLICATE KEY UPDATE `chuong_id`=VALUES(`chuong_id`), `tieu_de`=VALUES(`tieu_de`), `tom_tat`=VALUES(`tom_tat`), `tu_khoa`=VALUES(`tu_khoa`), `khung_hinh_phat`=VALUES(`khung_hinh_phat`), `can_cu_boi_thuong`=VALUES(`can_cu_boi_thuong`), `ghi_chu_quyen_loi`=VALUES(`ghi_chu_quyen_loi`);
INSERT INTO `khoan` (`dieu_luat_id`,`so_khoan`,`dieu_kien`,`noi_dung`,`quyen_loi`,`tu_khoa`,`ti_le_ton_thuong_min`,`ti_le_ton_thuong_max`,`gia_tri_tai_san_min`,`gia_tri_tai_san_max`,`so_nguoi_chet_min`) VALUES (353, 1, 'Tài sản chiếm đoạt trị giá từ 2 đến dưới 100 triệu đồng', 'Người nào lợi dụng chức vụ, quyền hạn chiếm đoạt tài sản mà mình có trách nhiệm quản lý trị giá từ 2 triệu đến dưới 100 triệu đồng (hoặc dưới 2 triệu nhưng có tình tiết tăng nặng) thì bị phạt tù từ 2 đến 7 năm.', NULL, 'hai triệu đến một trăm triệu', NULL, NULL, 2, 100, NULL) ON DUPLICATE KEY UPDATE `dieu_kien`=VALUES(`dieu_kien`), `noi_dung`=VALUES(`noi_dung`), `quyen_loi`=VALUES(`quyen_loi`), `tu_khoa`=VALUES(`tu_khoa`), `ti_le_ton_thuong_min`=VALUES(`ti_le_ton_thuong_min`), `ti_le_ton_thuong_max`=VALUES(`ti_le_ton_thuong_max`), `gia_tri_tai_san_min`=VALUES(`gia_tri_tai_san_min`), `gia_tri_tai_san_max`=VALUES(`gia_tri_tai_san_max`), `so_nguoi_chet_min`=VALUES(`so_nguoi_chet_min`);
INSERT INTO `khoan` (`dieu_luat_id`,`so_khoan`,`dieu_kien`,`noi_dung`,`quyen_loi`,`tu_khoa`,`ti_le_ton_thuong_min`,`ti_le_ton_thuong_max`,`gia_tri_tai_san_min`,`gia_tri_tai_san_max`,`so_nguoi_chet_min`) VALUES (353, 2, 'Tài sản 100–500 triệu đồng, hoặc có tổ chức', 'Chiếm đoạt tài sản trị giá 100 triệu đến dưới 500 triệu đồng, hoặc có tổ chức... thì bị phạt tù từ 7 đến 15 năm.', NULL, 'một trăm đến năm trăm triệu có tổ chức', NULL, NULL, 100, 500, NULL) ON DUPLICATE KEY UPDATE `dieu_kien`=VALUES(`dieu_kien`), `noi_dung`=VALUES(`noi_dung`), `quyen_loi`=VALUES(`quyen_loi`), `tu_khoa`=VALUES(`tu_khoa`), `ti_le_ton_thuong_min`=VALUES(`ti_le_ton_thuong_min`), `ti_le_ton_thuong_max`=VALUES(`ti_le_ton_thuong_max`), `gia_tri_tai_san_min`=VALUES(`gia_tri_tai_san_min`), `gia_tri_tai_san_max`=VALUES(`gia_tri_tai_san_max`), `so_nguoi_chet_min`=VALUES(`so_nguoi_chet_min`);
INSERT INTO `khoan` (`dieu_luat_id`,`so_khoan`,`dieu_kien`,`noi_dung`,`quyen_loi`,`tu_khoa`,`ti_le_ton_thuong_min`,`ti_le_ton_thuong_max`,`gia_tri_tai_san_min`,`gia_tri_tai_san_max`,`so_nguoi_chet_min`) VALUES (353, 3, 'Tài sản chiếm đoạt trị giá 500 triệu đến dưới 1 tỷ đồng', 'Chiếm đoạt tài sản trị giá 500 triệu đến dưới 1 tỷ đồng thì bị phạt tù từ 15 đến 20 năm.', NULL, 'năm trăm triệu đến một tỷ', NULL, NULL, 500, 1000, NULL) ON DUPLICATE KEY UPDATE `dieu_kien`=VALUES(`dieu_kien`), `noi_dung`=VALUES(`noi_dung`), `quyen_loi`=VALUES(`quyen_loi`), `tu_khoa`=VALUES(`tu_khoa`), `ti_le_ton_thuong_min`=VALUES(`ti_le_ton_thuong_min`), `ti_le_ton_thuong_max`=VALUES(`ti_le_ton_thuong_max`), `gia_tri_tai_san_min`=VALUES(`gia_tri_tai_san_min`), `gia_tri_tai_san_max`=VALUES(`gia_tri_tai_san_max`), `so_nguoi_chet_min`=VALUES(`so_nguoi_chet_min`);
INSERT INTO `khoan` (`dieu_luat_id`,`so_khoan`,`dieu_kien`,`noi_dung`,`quyen_loi`,`tu_khoa`,`ti_le_ton_thuong_min`,`ti_le_ton_thuong_max`,`gia_tri_tai_san_min`,`gia_tri_tai_san_max`,`so_nguoi_chet_min`) VALUES (353, 4, 'Tài sản chiếm đoạt trị giá từ 1 tỷ đồng trở lên', 'Chiếm đoạt tài sản trị giá 1 tỷ đồng trở lên thì bị phạt tù 20 năm, tù chung thân hoặc tử hình.', NULL, 'một tỷ trở lên', NULL, NULL, 1000, NULL, NULL) ON DUPLICATE KEY UPDATE `dieu_kien`=VALUES(`dieu_kien`), `noi_dung`=VALUES(`noi_dung`), `quyen_loi`=VALUES(`quyen_loi`), `tu_khoa`=VALUES(`tu_khoa`), `ti_le_ton_thuong_min`=VALUES(`ti_le_ton_thuong_min`), `ti_le_ton_thuong_max`=VALUES(`ti_le_ton_thuong_max`), `gia_tri_tai_san_min`=VALUES(`gia_tri_tai_san_min`), `gia_tri_tai_san_max`=VALUES(`gia_tri_tai_san_max`), `so_nguoi_chet_min`=VALUES(`so_nguoi_chet_min`);
INSERT INTO `dieu_luat` (`id`,`chuong_id`,`tieu_de`,`tom_tat`,`tu_khoa`,`khung_hinh_phat`,`can_cu_boi_thuong`,`ghi_chu_quyen_loi`) VALUES (134, (SELECT `id` FROM `chuong` WHERE `ten_chuong`='Các tội xâm phạm tính mạng, sức khỏe'), 'Tội cố ý gây thương tích hoặc gây tổn hại cho sức khỏe của người khác', 'Hành vi cố ý gây thương tích hoặc tổn hại sức khỏe cho người khác.', 'cố ý gây thương tích đánh nhau bạo lực tổn hại sức khỏe', 'Cải tạo không giam giữ đến 3 năm, hoặc phạt tù 6 tháng – 20 năm tùy tỉ lệ tổn thương', 'Điều 590 Bộ luật Dân sự 2015 — bồi thường thiệt hại do sức khỏe bị xâm phạm (Điều 591 nếu dẫn đến chết người)', NULL) ON DUPLICATE KEY UPDATE `chuong_id`=VALUES(`chuong_id`), `tieu_de`=VALUES(`tieu_de`), `tom_tat`=VALUES(`tom_tat`), `tu_khoa`=VALUES(`tu_khoa`), `khung_hinh_phat`=VALUES(`khung_hinh_phat`), `can_cu_boi_thuong`=VALUES(`can_cu_boi_thuong`), `ghi_chu_quyen_loi`=VALUES(`ghi_chu_quyen_loi`);
INSERT INTO `khoan` (`dieu_luat_id`,`so_khoan`,`dieu_kien`,`noi_dung`,`quyen_loi`,`tu_khoa`,`ti_le_ton_thuong_min`,`ti_le_ton_thuong_max`,`gia_tri_tai_san_min`,`gia_tri_tai_san_max`,`so_nguoi_chet_min`) VALUES (134, 1, 'Tỉ lệ tổn thương cơ thể 11–30%, hoặc dưới 11% nhưng có tình tiết tăng nặng (hung khí nguy hiểm, nạn nhân dưới 16 tuổi...)', 'Gây thương tích tỉ lệ tổn thương cơ thể từ 11% đến 30%, hoặc dưới 11% nhưng có tình tiết tăng nặng thì bị phạt cải tạo không giam giữ đến 3 năm hoặc phạt tù từ 6 tháng đến 3 năm.', 'Bạn có quyền yêu cầu người gây thương tích bồi thường: chi phí thực tế cho việc cứu chữa, bồi dưỡng, phục hồi sức khỏe; thu nhập thực tế bị mất hoặc giảm sút trong thời gian điều trị; và một khoản bù đắp tổn thất tinh thần do các bên thỏa thuận (nếu không thỏa thuận được, tối đa 50 lần mức lương cơ sở) — theo Điều 590 Bộ luật Dân sự.', 'mười một đến ba mươi phần trăm hung khí nguy hiểm', 11, 30, NULL, NULL, NULL) ON DUPLICATE KEY UPDATE `dieu_kien`=VALUES(`dieu_kien`), `noi_dung`=VALUES(`noi_dung`), `quyen_loi`=VALUES(`quyen_loi`), `tu_khoa`=VALUES(`tu_khoa`), `ti_le_ton_thuong_min`=VALUES(`ti_le_ton_thuong_min`), `ti_le_ton_thuong_max`=VALUES(`ti_le_ton_thuong_max`), `gia_tri_tai_san_min`=VALUES(`gia_tri_tai_san_min`), `gia_tri_tai_san_max`=VALUES(`gia_tri_tai_san_max`), `so_nguoi_chet_min`=VALUES(`so_nguoi_chet_min`);
INSERT INTO `khoan` (`dieu_luat_id`,`so_khoan`,`dieu_kien`,`noi_dung`,`quyen_loi`,`tu_khoa`,`ti_le_ton_thuong_min`,`ti_le_ton_thuong_max`,`gia_tri_tai_san_min`,`gia_tri_tai_san_max`,`so_nguoi_chet_min`) VALUES (134, 2, 'Tỉ lệ tổn thương cơ thể 31–60%, hoặc 11–30% nhưng có tình tiết tăng nặng', 'Tỉ lệ tổn thương từ 31% đến 60%, hoặc từ 11–30% nhưng có tình tiết tăng nặng thì bị phạt tù từ 2 đến 6 năm.', 'Ngoài các khoản như khoản 1, với tỉ lệ tổn thương cao hơn bạn còn có thể yêu cầu thêm chi phí hợp lý và thu nhập bị mất của người chăm sóc trong thời gian điều trị (nếu sức khỏe suy giảm cần có người chăm sóc) — theo Điều 590 Bộ luật Dân sự.', 'ba mươi mốt đến sáu mươi phần trăm', 31, 60, NULL, NULL, NULL) ON DUPLICATE KEY UPDATE `dieu_kien`=VALUES(`dieu_kien`), `noi_dung`=VALUES(`noi_dung`), `quyen_loi`=VALUES(`quyen_loi`), `tu_khoa`=VALUES(`tu_khoa`), `ti_le_ton_thuong_min`=VALUES(`ti_le_ton_thuong_min`), `ti_le_ton_thuong_max`=VALUES(`ti_le_ton_thuong_max`), `gia_tri_tai_san_min`=VALUES(`gia_tri_tai_san_min`), `gia_tri_tai_san_max`=VALUES(`gia_tri_tai_san_max`), `so_nguoi_chet_min`=VALUES(`so_nguoi_chet_min`);
INSERT INTO `khoan` (`dieu_luat_id`,`so_khoan`,`dieu_kien`,`noi_dung`,`quyen_loi`,`tu_khoa`,`ti_le_ton_thuong_min`,`ti_le_ton_thuong_max`,`gia_tri_tai_san_min`,`gia_tri_tai_san_max`,`so_nguoi_chet_min`) VALUES (134, 3, 'Tỉ lệ tổn thương từ 61% trở lên, hoặc dẫn đến chết người', 'Tỉ lệ tổn thương 61% trở lên, hoặc dẫn đến chết người, thì bị phạt tù từ 5 đến 10 năm hoặc cao hơn tùy tình tiết.', 'Nếu còn sống: được bồi thường đầy đủ các khoản ở Điều 590 (cứu chữa, thu nhập mất, người chăm sóc, tổn thất tinh thần), mức tổn thất tinh thần thường được xem xét ở ngưỡng cao hơn do hậu quả nghiêm trọng. Nếu dẫn đến chết người: thân nhân chuyển sang quyền yêu cầu bồi thường theo Điều 591 (chi phí mai táng, tiền cấp dưỡng, tổn thất tinh thần tối đa 100 lần mức lương cơ sở).', 'sáu mươi mốt phần trăm trở lên chết người', 61, NULL, NULL, NULL, NULL) ON DUPLICATE KEY UPDATE `dieu_kien`=VALUES(`dieu_kien`), `noi_dung`=VALUES(`noi_dung`), `quyen_loi`=VALUES(`quyen_loi`), `tu_khoa`=VALUES(`tu_khoa`), `ti_le_ton_thuong_min`=VALUES(`ti_le_ton_thuong_min`), `ti_le_ton_thuong_max`=VALUES(`ti_le_ton_thuong_max`), `gia_tri_tai_san_min`=VALUES(`gia_tri_tai_san_min`), `gia_tri_tai_san_max`=VALUES(`gia_tri_tai_san_max`), `so_nguoi_chet_min`=VALUES(`so_nguoi_chet_min`);
INSERT INTO `dieu_luat` (`id`,`chuong_id`,`tieu_de`,`tom_tat`,`tu_khoa`,`khung_hinh_phat`,`can_cu_boi_thuong`,`ghi_chu_quyen_loi`) VALUES (249, (SELECT `id` FROM `chuong` WHERE `ten_chuong`='Các tội phạm về ma túy'), 'Tội tàng trữ trái phép chất ma túy', 'Tàng trữ trái phép chất ma túy mà không nhằm mục đích mua bán, vận chuyển, sản xuất.', 'ma túy tàng trữ trái phép chất cấm sử dụng', '1 – 20 năm tù hoặc tù chung thân tùy khối lượng', NULL, 'Đây là tội phạm không có người bị hại cụ thể (xâm phạm trật tự quản lý về ma túy), nên không phát sinh quyền yêu cầu bồi thường dân sự.') ON DUPLICATE KEY UPDATE `chuong_id`=VALUES(`chuong_id`), `tieu_de`=VALUES(`tieu_de`), `tom_tat`=VALUES(`tom_tat`), `tu_khoa`=VALUES(`tu_khoa`), `khung_hinh_phat`=VALUES(`khung_hinh_phat`), `can_cu_boi_thuong`=VALUES(`can_cu_boi_thuong`), `ghi_chu_quyen_loi`=VALUES(`ghi_chu_quyen_loi`);
INSERT INTO `khoan` (`dieu_luat_id`,`so_khoan`,`dieu_kien`,`noi_dung`,`quyen_loi`,`tu_khoa`,`ti_le_ton_thuong_min`,`ti_le_ton_thuong_max`,`gia_tri_tai_san_min`,`gia_tri_tai_san_max`,`so_nguoi_chet_min`) VALUES (249, 1, 'Khối lượng ở mức khởi điểm theo quy định', 'Tàng trữ trái phép chất ma túy với khối lượng ở mức khởi điểm theo quy định thì bị phạt tù từ 1 đến 5 năm.', NULL, 'khối lượng mức khởi điểm', NULL, NULL, NULL, NULL, NULL) ON DUPLICATE KEY UPDATE `dieu_kien`=VALUES(`dieu_kien`), `noi_dung`=VALUES(`noi_dung`), `quyen_loi`=VALUES(`quyen_loi`), `tu_khoa`=VALUES(`tu_khoa`), `ti_le_ton_thuong_min`=VALUES(`ti_le_ton_thuong_min`), `ti_le_ton_thuong_max`=VALUES(`ti_le_ton_thuong_max`), `gia_tri_tai_san_min`=VALUES(`gia_tri_tai_san_min`), `gia_tri_tai_san_max`=VALUES(`gia_tri_tai_san_max`), `so_nguoi_chet_min`=VALUES(`so_nguoi_chet_min`);
INSERT INTO `khoan` (`dieu_luat_id`,`so_khoan`,`dieu_kien`,`noi_dung`,`quyen_loi`,`tu_khoa`,`ti_le_ton_thuong_min`,`ti_le_ton_thuong_max`,`gia_tri_tai_san_min`,`gia_tri_tai_san_max`,`so_nguoi_chet_min`) VALUES (249, 2, 'Có tổ chức, tái phạm nguy hiểm, khối lượng lớn hơn mức khởi điểm', 'Có tổ chức, tái phạm nguy hiểm, khối lượng lớn hơn mức khởi điểm... thì bị phạt tù từ 5 đến 15 năm.', NULL, 'có tổ chức tái phạm nguy hiểm khối lượng lớn hơn', NULL, NULL, NULL, NULL, NULL) ON DUPLICATE KEY UPDATE `dieu_kien`=VALUES(`dieu_kien`), `noi_dung`=VALUES(`noi_dung`), `quyen_loi`=VALUES(`quyen_loi`), `tu_khoa`=VALUES(`tu_khoa`), `ti_le_ton_thuong_min`=VALUES(`ti_le_ton_thuong_min`), `ti_le_ton_thuong_max`=VALUES(`ti_le_ton_thuong_max`), `gia_tri_tai_san_min`=VALUES(`gia_tri_tai_san_min`), `gia_tri_tai_san_max`=VALUES(`gia_tri_tai_san_max`), `so_nguoi_chet_min`=VALUES(`so_nguoi_chet_min`);
INSERT INTO `khoan` (`dieu_luat_id`,`so_khoan`,`dieu_kien`,`noi_dung`,`quyen_loi`,`tu_khoa`,`ti_le_ton_thuong_min`,`ti_le_ton_thuong_max`,`gia_tri_tai_san_min`,`gia_tri_tai_san_max`,`so_nguoi_chet_min`) VALUES (249, 3, 'Khối lượng đặc biệt lớn', 'Khối lượng đặc biệt lớn thì bị phạt tù 15–20 năm hoặc tù chung thân.', NULL, 'khối lượng đặc biệt lớn', NULL, NULL, NULL, NULL, NULL) ON DUPLICATE KEY UPDATE `dieu_kien`=VALUES(`dieu_kien`), `noi_dung`=VALUES(`noi_dung`), `quyen_loi`=VALUES(`quyen_loi`), `tu_khoa`=VALUES(`tu_khoa`), `ti_le_ton_thuong_min`=VALUES(`ti_le_ton_thuong_min`), `ti_le_ton_thuong_max`=VALUES(`ti_le_ton_thuong_max`), `gia_tri_tai_san_min`=VALUES(`gia_tri_tai_san_min`), `gia_tri_tai_san_max`=VALUES(`gia_tri_tai_san_max`), `so_nguoi_chet_min`=VALUES(`so_nguoi_chet_min`);
INSERT INTO `dieu_luat` (`id`,`chuong_id`,`tieu_de`,`tom_tat`,`tu_khoa`,`khung_hinh_phat`,`can_cu_boi_thuong`,`ghi_chu_quyen_loi`) VALUES (321, (SELECT `id` FROM `chuong` WHERE `ten_chuong`='Các tội xâm phạm trật tự quản lý kinh tế'), 'Tội đánh bạc', 'Đánh bạc trái phép dưới bất kỳ hình thức nào được thua bằng tiền hay hiện vật trị giá từ mức quy định trở lên.', 'đánh bạc cờ bạc tổ chức trò chơi ăn tiền', 'Phạt tiền, cải tạo không giam giữ đến 3 năm, hoặc phạt tù đến 7 năm', NULL, 'Đây là tội phạm không có người bị hại (những người tham gia đều tự nguyện), nên không phát sinh quyền yêu cầu bồi thường dân sự giữa các bên; tiền/hiện vật dùng đánh bạc có thể bị tịch thu sung công quỹ Nhà nước.') ON DUPLICATE KEY UPDATE `chuong_id`=VALUES(`chuong_id`), `tieu_de`=VALUES(`tieu_de`), `tom_tat`=VALUES(`tom_tat`), `tu_khoa`=VALUES(`tu_khoa`), `khung_hinh_phat`=VALUES(`khung_hinh_phat`), `can_cu_boi_thuong`=VALUES(`can_cu_boi_thuong`), `ghi_chu_quyen_loi`=VALUES(`ghi_chu_quyen_loi`);
INSERT INTO `khoan` (`dieu_luat_id`,`so_khoan`,`dieu_kien`,`noi_dung`,`quyen_loi`,`tu_khoa`,`ti_le_ton_thuong_min`,`ti_le_ton_thuong_max`,`gia_tri_tai_san_min`,`gia_tri_tai_san_max`,`so_nguoi_chet_min`) VALUES (321, 1, 'Tiền/hiện vật dùng đánh bạc trị giá 5–50 triệu đồng', 'Đánh bạc trái phép được thua bằng tiền hay hiện vật trị giá từ 5 triệu đến dưới 50 triệu đồng (hoặc dưới 5 triệu nhưng đã bị xử phạt/kết án về hành vi này) thì bị phạt tiền 20–100 triệu đồng, cải tạo không giam giữ đến 3 năm hoặc phạt tù từ 6 tháng đến 3 năm.', NULL, 'năm triệu đến năm mươi triệu', NULL, NULL, 5, 50, NULL) ON DUPLICATE KEY UPDATE `dieu_kien`=VALUES(`dieu_kien`), `noi_dung`=VALUES(`noi_dung`), `quyen_loi`=VALUES(`quyen_loi`), `tu_khoa`=VALUES(`tu_khoa`), `ti_le_ton_thuong_min`=VALUES(`ti_le_ton_thuong_min`), `ti_le_ton_thuong_max`=VALUES(`ti_le_ton_thuong_max`), `gia_tri_tai_san_min`=VALUES(`gia_tri_tai_san_min`), `gia_tri_tai_san_max`=VALUES(`gia_tri_tai_san_max`), `so_nguoi_chet_min`=VALUES(`so_nguoi_chet_min`);
